def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    last_op = op[-1]
    last_my = my[-1]

    opp_def = 0
    opp_coop = 0
    for a in op:
        if a == 'D':
            opp_def += 1
        else:
            opp_coop += 1

    # recent windows
    w10 = op[-10:]
    w6 = op[-6:]
    w4 = op[-4:]

    def count_val(seq, val):
        c = 0
        for a in seq:
            if a == val:
                c += 1
        return c

    coop10 = count_val(w10, 'C')
    coop6 = count_val(w6, 'C')
    coop4 = count_val(w4, 'C')

    # tail defection streak
    tail_def = 0
    for a in reversed(op):
        if a == 'D':
            tail_def += 1
        else:
            break

    # tail mutual cooperation streak
    tail_cc = 0
    for i in range(n - 1, -1, -1):
        if my[i] == 'C' and op[i] == 'C':
            tail_cc += 1
        else:
            break

    remaining = 100 - n

    # Establish cooperation at start
    if n <= 2:
        if last_op == 'D':
            return 'D'
        return 'C'

    # If opponent just defected:
    if last_op == 'D':
        # long defect streak -> defect
        if tail_def >= 3:
            return 'D'
        # high overall defection rate -> mostly defect
        if opp_def * 2 > n:
            return 'D'
        # if we've been cooperating and it's isolated, forgive with decent probability
        if last_my == 'C' and tail_def == 1 and opp_def * 5 < n:
            if rng.random() < 0.75:
                return 'C'
        # moderate defection rate -> defect
        if coop10 <= 5:
            return 'D'
        # otherwise retaliate but allow forgiveness
        if rng.random() < 0.35:
            return 'C'
        return 'D'

    # Opponent cooperated last
    # If opponent is extremely cooperative
    if opp_def == 0:
        # exploit at the very end
        if remaining <= 2:
            return 'D'
        # occasional probe, but not too often to avoid breaking cooperation
        if n >= 12 and n % 13 == 0:
            return 'D'
        return 'C'

    # Opponent mostly cooperative
    if opp_def * 5 <= n:
        # late-game exploitation
        if remaining <= 2:
            return 'D'
        # if we defected last and they still cooperated, exploit a bit more
        if last_my == 'D':
            if remaining > 4 and rng.random() < 0.55:
                return 'D'
            return 'C'
        # occasional opportunistic probe when in long CC streak
        if tail_cc >= 5 and rng.random() < 0.06:
            return 'D'
        return 'C'

    # Opponent moderately defective
    if opp_def * 2 > n:
        # they defect a lot; if they cooperated now, maybe reciprocate once
        if tail_def >= 2:
            return 'D'
        if rng.random() < 0.25:
            return 'C'
        return 'D'

    # Opponent is mixed
    if coop6 >= 4:
        if rng.random() < 0.1:
            return 'D'
        return 'C'
    if coop6 <= 2:
        return 'D'

    # default reciprocation with slight forgiveness
    if last_my == 'D':
        return 'C'
    return 'C'
